local function beast(ctx,e)for _,t in ipairs(ctx:card_definition(ctx:entity(e).card_id).tags or{})do if t=="beast"or t=="all"then return true end end return false end
return {api_version=1,id="EX1_531",name="Scavenging Hyena",text="Whenever a friendly Beast dies, gain +2/+1.",set="EXPERT1",type="minion",class="hunter",rarity="common",cost=2,attack=2,health=2,tags={"beast"},triggers={{event="entity_died",timing="after",active_zones={"board"},condition=function(ctx,self,e)return e.player==ctx:controller(self)and beast(ctx,e.entity)end,effect=function(ctx,self)ctx:buff(self,2,1)end}}}
